// The transform spaces 1.x knew by names of its own are written as the engine's (DSH5278 each); a TransformPosition
// with no Destination goes to World, as in 1.x; TranslatedWorldPosition is WorldPosition at CameraRelative.
/// @name M_LpTransformSpaces
export void M_LpTransformSpaces(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float3 Camera = UE.WorldPosition(WorldPositionShaderOffset = CameraRelative);
    float3 Placed = UE.TransformPosition(Camera, Source = "TranslatedWorld", Destination = World);
    float3 Person = UE.TransformPosition(Placed, Source = World, Destination = "FirstPersonTranslatedWorld");
    float3 Direction = UE.TransformVector(Placed, Source = "World", Destination = "Instance");
    Color = Person + Direction;
    Base.EmissiveColor = Color;
}
